-- 1. Add missing columns to impact_hero
ALTER TABLE impact_hero
  ADD COLUMN heading TEXT AFTER section_subtitle,
  ADD COLUMN description TEXT AFTER heading,
  ADD COLUMN cta_primary VARCHAR(255) DEFAULT 'View Impact Dashboard' AFTER description,
  ADD COLUMN cta_secondary VARCHAR(255) DEFAULT 'SDG Contributions' AFTER cta_primary;

-- 2. Seed impact_hero with current hardcoded values
UPDATE impact_hero SET
  hero_image = 'assets/images/hero.jpg',
  section_title = 'Impact & SDG Center',
  section_subtitle = 'Every data point represents a life touched. Our Impact & SDG Center tracks outcomes, ensures accountability, and drives continuous improvement across every WRC program.',
  heading = 'Measuring What Matters,<br>Changing What Counts.',
  description = 'Every data point represents a life touched. Our Impact & SDG Center tracks outcomes, ensures accountability, and drives continuous improvement across every WRC program.',
  cta_primary = 'View Impact Dashboard',
  cta_secondary = 'SDG Contributions'
WHERE id = 1;

